// 确定单坐标最终位置
int solve(int num, int div) {
    int mul = num / div;
    int mod = num % div;
    // 2的倍数相当于从头开始
    if (mul % 2 == 0) {
        return mod;
    } else {
        return div - mod;
    }
}
