// 确定单坐标最终位置
func solve(num, div int) int {
    mul := num / div
    mod := num % div
    // 2的倍数相当于从头开始
    if mul%2 == 0 {
        return mod
    } else {
        return div - mod
    }
}
​
func main() {
    var x, y, t int
    fmt.Scan(&x, &y, &t)
​
    newX := x + t
    newY := y + t
​
    // 800 - 50 = 750
